-- Phase 36.4: client requests (docs/data-model.md `client_requests`; docs/screens.md "## Phase 36").
-- Generated by drizzle-kit, then by hand: these comments and the "Tell me about" step at the end.
-- - client_requests: what a client contact asks the office for (a new event, more or fewer places,
--   new times, cancel a session, something else), its payload (checked in code per kind), the
--   client's note, its status (waiting, accepted, declined, asked, done_in_planner), whether the
--   rules found it urgent, the office's answer (who, when; a decline and a question always carry
--   words) and, for a planner's session, when the office marked it done there. Goes with its
--   contract and its contact (CASCADE); its session, event and office users by composite FKs.
-- - office_users.tell_me: a new kind, 'client_requests' (a notification for an urgent one), on by
--   default: added to every saved choice too, so people who changed a switch before get it as well.
CREATE TABLE "client_requests" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"firm_id" uuid NOT NULL,
	"contract_id" uuid NOT NULL,
	"client_contact_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"shift_id" uuid,
	"event_id" uuid,
	"payload" jsonb NOT NULL,
	"client_note" text,
	"status" text DEFAULT 'waiting' NOT NULL,
	"urgent" boolean DEFAULT false NOT NULL,
	"office_answer" text,
	"answered_by" uuid,
	"answered_at" timestamp with time zone,
	"planner_done_at" timestamp with time zone,
	"planner_done_by" uuid,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "client_requests_firm_id_id_key" UNIQUE("firm_id","id"),
	CONSTRAINT "client_requests_kind_check" CHECK ("client_requests"."kind" in ('new_event', 'more_places', 'fewer_places', 'new_times', 'cancel_session', 'other')),
	CONSTRAINT "client_requests_status_check" CHECK ("client_requests"."status" in ('waiting', 'accepted', 'declined', 'asked', 'done_in_planner')),
	CONSTRAINT "client_requests_session_kinds" CHECK (("client_requests"."kind" in ('more_places', 'fewer_places', 'new_times', 'cancel_session')) = ("client_requests"."shift_id" is not null)
        or "client_requests"."kind" = 'other'),
	CONSTRAINT "client_requests_payload_object" CHECK (jsonb_typeof("client_requests"."payload") = 'object'),
	CONSTRAINT "client_requests_note_length" CHECK ("client_requests"."client_note" is null or char_length("client_requests"."client_note") between 1 and 1000),
	CONSTRAINT "client_requests_answer_length" CHECK ("client_requests"."office_answer" is null or char_length("client_requests"."office_answer") between 1 and 1000),
	CONSTRAINT "client_requests_answer_shape" CHECK (("client_requests"."status" = 'waiting' or ("client_requests"."answered_by" is not null and "client_requests"."answered_at" is not null))
        and ("client_requests"."status" not in ('declined', 'asked') or "client_requests"."office_answer" is not null)),
	CONSTRAINT "client_requests_planner_done" CHECK (("client_requests"."planner_done_at" is null) = ("client_requests"."planner_done_by" is null)
        and ("client_requests"."planner_done_at" is null or "client_requests"."status" = 'done_in_planner'))
);
--> statement-breakpoint
