CREATE POLICY "firm_isolation" ON "client_requests" AS PERMISSIVE FOR ALL TO public USING ("client_requests"."firm_id" = (select app_current_firm_id())) WITH CHECK ("client_requests"."firm_id" = (select app_current_firm_id()));--> statement-breakpoint
-- "Tell me about: client requests" is on by default (Dylan, 2026-11-11), for people who had saved
-- their own choice too. Forced RLS binds the owner on firms' tables, so each firm is set in turn
-- (as 0073 does), and the setting is cleared at the end.
DO $$
DECLARE
  f record;
BEGIN
  FOR f IN SELECT id FROM public.firms ORDER BY id LOOP
    PERFORM set_config('app.current_firm_id', f.id::text, true);
    UPDATE public.office_users
       SET tell_me = array_append(tell_me, 'client_requests')
     WHERE firm_id = f.id AND tell_me IS NOT NULL
       AND NOT (tell_me @> array['client_requests']::text[]);
  END LOOP;
  PERFORM set_config('app.current_firm_id', '', true);
END $$;
